/**
 * Exact differential test of browser ELF loading and recurrent-state encoding.
 * Expected snapshots were generated by upstream chipformer.rv.core.snapshot;
 * they are independent of this JavaScript port (MIT, Divyansh Agrawal).
 */
import assert from 'node:assert/strict';
import {readFile,readdir} from 'node:fs/promises';
import {gunzipSync} from 'node:zlib';
import {buildSnapshot,parseELF} from '../dist/machine/snapshot.js';

const assets=new URL('../dist/machine/',import.meta.url);
const fixtures=new URL('fixtures/',assets);
const circuit=JSON.parse(gunzipSync(await readFile(new URL('neural-circuit.json.gz',assets))));
const names=(await readdir(fixtures)).filter(n=>n.endsWith('.snapshot.json.gz')).map(n=>n.slice(0,-'.snapshot.json.gz'.length)).sort();
assert.ok(names.length>=50,'Expected the supplied ISA, C, and MicroPython fixtures');
for(const name of ['c-fib','mpy-s1','mpy-s5','rv32ui-addi','rv32um-mulhu'])assert.ok(names.includes(name),`Missing required fixture ${name}`);

function denseRow(raw){
  if(ArrayBuffer.isView(raw))return raw;
  const row=new Float64Array(128);
  if(raw.length===128&&typeof raw[0]==='number')row.set(raw);
  else for(const [col,value]of raw)row[col]=value;
  return row;
}
let totalRows=0;
for(const name of names){
  const elf=await readFile(new URL(`${name}.elf`,fixtures));
  const actual=buildSnapshot(elf,circuit,{name});
  const expected=JSON.parse(gunzipSync(await readFile(new URL(`${name}.snapshot.json.gz`,fixtures))));
  assert.equal(actual.pc,expected.pc,`${name}: initial PC`);
  assert.equal(actual.startToken,expected.startToken,`${name}: start token`);
  assert.deepEqual(Object.keys(actual.states).sort(),Object.keys(expected.states).sort(),`${name}: table set`);
  for(const [node,heads]of Object.entries(expected.states)){
    assert.equal(actual.states[node].length,heads.length,`${name}: value-head count at ${node}`);
    for(let vh=0;vh<heads.length;vh++){
      assert.deepEqual(Object.keys(actual.states[node][vh]).sort(),Object.keys(heads[vh]).sort(),`${name}: present rows at ${node}/${vh}`);
      for(const [row,values]of Object.entries(heads[vh])){
        assert.deepEqual(actual.states[node][vh][row],denseRow(values),`${name}: row ${node}/${vh}/${row}`);
        totalRows++;
      }
    }
  }
}
// Upload validation: a malformed or incorrectly linked binary must not silently
// become a different program in the circuit's restricted address map.
const valid=await readFile(new URL('c-fib.elf',fixtures));
assert.throws(()=>parseELF(valid.subarray(0,20)),/truncated/);
const wrongMachine=Buffer.from(valid);wrongMachine.writeUInt16LE(62,18);
assert.throws(()=>parseELF(wrongMachine),/RISC-V/);
const compressed=Buffer.from(valid);compressed.writeUInt32LE(1,36);
assert.throws(()=>parseELF(compressed),/Compressed RISC-V/);
const badEntry=Buffer.from(valid);badEntry.writeUInt32LE(0x80000000,24);
assert.throws(()=>parseELF(badEntry),/Entry point/);
const badSegment=Buffer.from(valid),phoff=badSegment.readUInt32LE(28),stride=badSegment.readUInt16LE(42),count=badSegment.readUInt16LE(44);
for(let i=0;i<count;i++){const at=phoff+i*stride;if(badSegment.readUInt32LE(at)===1&&badSegment.readUInt32LE(at+20)>0){badSegment.writeUInt32LE(0x10000000,at+8);break;}}
assert.throws(()=>parseELF(badSegment),/does not fit/);
console.log(`Snapshot differential checks passed: ${names.length} ELF fixtures, ${totalRows.toLocaleString('en-US')} exact recurrent-state rows; malformed uploads rejected.`);
